def get_vm_ref(vm_name, datacenter, service_instance=None):
    """
    Returns a VM object reference from a virtual machine name

    vm_name
        Virtual machine name

    datacenter
        Datacenter name where the virtual machine is available

    service_instance
        vCenter service instance for connection and configuration
    """
    if not service_instance:
        service_instance = get_service_instance(opts=__opts__, conn=__proxy__)
    vm_ref = None
    for dc in service_instance.content.rootFolder.childEntity:
        if dc.name == datacenter:
            for vm in dc.vmFolder.childEntity:
                if vm.name == vm_name:
                    vm_ref = vm
    return vm_ref


def get_vm_summary(vm_name, datacenter, service_instance=None):
    """
    Returns a VM object summary from a virtual machine name

    vm_name
        Virtual machine name

    datacenter
        Datacenter name where the virtual machine is available

    service_instance
        vCenter service instance for connection and configuration
    """
    if not service_instance:
        service_instance = get_service_instance(opts=__opts__, conn=__proxy__)
    vm_ref = get_vm_ref(vm_name, datacenter, service_instance)
    if not vm_ref:
        return {}
    return vm_ref.summary


